#include <iostream>
#include <vector>
#include <algorithm>
#include <iomanip>
#include <cmath>

using namespace std;

/**
 * Problem: 10505 - Center of Masses
 * 
 * 解題思路：
 * 1. 給定凸多邊形的頂點（無序），首先需要對頂點進行排序以形成邊界。可以使用凸包算法（如 Monotone Chain）。
 * 2. 凸多邊形的質心（Centroid）公式為：
 *    A = 1/2 * Σ (x_i * y_{i+1} - x_{i+1} * y_i)
 *    Cx = 1/(6A) * Σ (x_i + x_{i+1}) * (x_i * y_{i+1} - x_{i+1} * y_i)
 *    Cy = 1/(6A) * Σ (y_i + y_{i+1}) * (x_i * y_{i+1} - x_{i+1} * y_i)
 *    其中頂點需按順序排列，且最後一個點與第一個點相連。
 */

struct Point {
    double x, y;
    bool operator<(const Point& other) const {
        if (x != other.x) return x < other.x;
        return y < other.y;
    }
};

double cross_product(Point a, Point b, Point c) {
    return (b.x - a.x) * (c.y - a.y) - (b.y - a.y) * (c.x - a.x);
}

vector<Point> get_convex_hull(vector<Point>& pts) {
    int n = pts.size();
    if (n <= 2) return pts;
    sort(pts.begin(), pts.end());
    vector<Point> hull;
    // Lower hull
    for (int i = 0; i < n; ++i) {
        while (hull.size() >= 2 && cross_product(hull[hull.size() - 2], hull.back(), pts[i]) <= 0) {
            hull.pop_back();
        }
        hull.push_back(pts[i]);
    }
    // Upper hull
    int lower_size = hull.size();
    for (int i = n - 2; i >= 0; --i) {
        while (hull.size() > lower_size && cross_product(hull[hull.size() - 2], hull.back(), pts[i]) <= 0) {
            hull.pop_back();
        }
        hull.push_back(pts[i]);
    }
    hull.pop_back(); // Remove last duplicate of first point
    return hull;
}

int main() {
    int n;
    while (cin >> n && n >= 3) {
        vector<Point> pts(n);
        for (int i = 0; i < n; ++i) {
            cin >> pts[i].x >> pts[i].y;
        }

        vector<Point> hull = get_convex_hull(pts);
        int m = hull.size();

        double area = 0;
        double cx = 0, cy = 0;
        for (int i = 0; i < m; ++i) {
            int next = (i + 1) % m;
            double factor = (hull[i].x * hull[next].y - hull[next].x * hull[i].y);
            area += factor;
            cx += (hull[i].x + hull[next].x) * factor;
            cy += (hull[i].y + hull[next].y) * factor;
        }

        area *= 0.5;
        cx /= (6.0 * area);
        cy /= (6.0 * area);

        cout << fixed << setprecision(3) << cx << " " << cy << endl;
    }
    return 0;
}
